const lessons=[{"sentences":[{"speaker":"A","text":"Attention all staff members regarding the upcoming annual technology conference happening next month.","position":1,"audioStartSeconds":0,"audioEndSeconds":6.448291666666667},{"speaker":"A","text":"Please remember that early registration discounts will end this coming Friday afternoon.","position":2,"audioStartSeconds":6.648291666666666,"audioEndSeconds":11.97125},{"speaker":"A","text":"If you register after this deadline you must pay the full ticket price.","position":3,"audioStartSeconds":12.17125,"audioEndSeconds":16.874833333333335},{"speaker":"A","text":"You can find the online sign up form on our internal company website.","position":4,"audioStartSeconds":17.074833333333334,"audioEndSeconds":21.68825},{"speaker":"A","text":"Human resources will send a confirmation email once your payment is successfully processed.","position":5,"audioStartSeconds":21.88825,"audioEndSeconds":27.674333333333333},{"speaker":"A","text":"Please contact our support desk if you experience technical issues while submitting forms.","position":6,"audioStartSeconds":27.874333333333333,"audioEndSeconds":33.64754166666667},{"speaker":"A","text":"We look forward to seeing everyone participate in this important professional development event.","position":7,"audioStartSeconds":33.847541666666665,"audioEndSeconds":39.46608333333333},{"speaker":"A","role":"section-start","text":"Please note that the room location for the morning marketing presentation has just changed.","position":8,"audioStartSeconds":44.46608333333333,"audioEndSeconds":49.878458333333334},{"speaker":"A","text":"We were originally scheduled to meet in room four hundred inside the main building.","position":9,"audioStartSeconds":50.07845833333333,"audioEndSeconds":54.936708333333335},{"speaker":"A","text":"However maintenance work will take place in that area throughout the entire morning.","position":10,"audioStartSeconds":55.13670833333333,"audioEndSeconds":60.18825},{"speaker":"A","text":"Therefore we have moved the session to the conference hall on the ground floor.","position":11,"audioStartSeconds":60.38825,"audioEndSeconds":65.01454166666667},{"speaker":"A","text":"Staff members should arrive ten minutes early to find their seats comfortably.","position":12,"audioStartSeconds":65.21454166666666,"audioEndSeconds":70.07279166666666},{"speaker":"A","text":"Updated printed schedules are now available at the main reception desk.","position":13,"audioStartSeconds":70.27279166666666,"audioEndSeconds":75.01504166666666},{"speaker":"A","text":"Thank you for your patience and understanding regarding this unexpected adjustment.","position":14,"audioStartSeconds":75.21504166666666,"audioEndSeconds":80.3715}],"questions":[{"prompt":"What is the main topic of the first announcement?","options":["A technology conference registration.","An office furniture purchase.","A software update procedure."],"answer":"A","evidenceSentence":1,"evidence":"Attention all staff members regarding the upcoming annual technology conference","explanation":"Thông báo đầu tiên nói về hội nghị công nghệ thường niên sắp tới."},{"prompt":"When do the early registration discounts finish?","options":["This coming Friday afternoon.","Next Monday morning.","By the end of today."],"answer":"A","evidenceSentence":2,"evidence":"early registration discounts will end this coming Friday afternoon","explanation":"Giảm giá đăng ký sớm sẽ kết thúc vào chiều thứ Sáu tới."},{"prompt":"What will happen if employees register after the deadline?","options":["They must pay the full ticket price.","Their application will be rejected.","They will receive a smaller discount."],"answer":"A","evidenceSentence":3,"evidence":"If you register after this deadline you must pay the full ticket price","explanation":"Nếu đăng ký sau thời hạn, nhân viên phải trả toàn bộ giá vé."},{"prompt":"What change has been made to the morning marketing presentation?","options":["The room location has changed.","The starting time was delayed.","The guest speaker was replaced."],"answer":"A","evidenceSentence":8,"evidence":"the room location for the morning marketing presentation has just changed","explanation":"Địa điểm phòng họp cho buổi thuyết trình tiếp thị buổi sáng đã thay đổi."},{"prompt":"Why was the room location changed?","options":["Maintenance work will happen in the old area.","The original room was too small.","Another department booked the space."],"answer":"A","evidenceSentence":10,"evidence":"maintenance work will take place in that area throughout the entire morning","explanation":"Công việc bảo trì sẽ diễn ra ở khu vực phòng cũ trong suốt buổi sáng."},{"prompt":"Where should attendees get updated printed schedules?","options":["At the main reception desk.","From the human resources office.","Inside the conference hall."],"answer":"A","evidenceSentence":13,"evidence":"Updated printed schedules are now available at the main reception desk","explanation":"Lịch trình in cập nhật hiện có sẵn tại quầy lễ tân chính."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
